            ni, nj = i + di, j + dj
            if 0 <= ni < len(grid) and 0 <= nj < len(grid[ni]) and grid[ni][nj] != 'X':
                G.add_edge((i, j), (ni, nj))

    # Perform graph clustering
    clusters = list(nx.connected_components(G))

    # Find the goal state
