    # Group states into abstract states
    grouped_states = []
    for c in clusters:
        if goal_state not in c:  # Goal state is in a separate cluster
            continue
        cluster = set(c) | {goal_state}
        min_distance = float('inf')
        target_state = None
        for s in cluster:
            distance = abs(s[0] - goal_state[0]) + abs(s[1] - goal_state[1])
